const items = $input.all();
const results = [];
const benchmarks = { 'Jardim America': 6800, 'Altos da Cidade': 5400, 'Vila Aviacao': 8200, 'Vila Universitaria': 5100, 'Parque das Nacoes': 3200, 'Nucleo Mary Dota': 2700, 'Centro': 3900, 'Geral': 4200 };
for (const item of items) {
  const im = item.json;
  const price = Number(im.price || 0);
  const area = Number(im.area_m2 || 0);
  if (price <= 0 || area <= 0) continue;
  const calculatedM2 = price / area;
  const neighborhood = im.neighborhood || 'Geral';
  const bench = benchmarks[neighborhood] || benchmarks['Geral'];
  const marketEst = bench * area;
  const discount = ((marketEst - price) / marketEst) * 100;
  const netProfit = marketEst - price;
  let score = 50;
  let priority = 'NORMAL';
  if (discount >= 40) { score = 98; priority = 'CRITICAL_BUG'; }
  else if (discount >= 25) { score = 85; priority = 'HIGH'; }
  else if (discount >= 15) { score = 70; }
  if (score >= 70) {
    results.push({
      json: {
        category: 'real_estate_local',
        title: `${im.title || 'Imóvel'} em ${neighborhood} (Bauru)`,
        description: `R$ ${calculatedM2.toFixed(0)}/m² vs Méd. Região R$ ${bench}/m² (${discount.toFixed(1)}% de deságio)`,
        original_price: marketEst,
        opportunity_price: price,
        discount_percentage: Number(discount.toFixed(2)),
        net_profit_estimate: Number(netProfit.toFixed(2)),
        fipe_or_market_ref: marketEst,
        location: `Bauru - SP (${neighborhood})`,
        source_name: im.source || 'Radar Imobiliário Bauru',
        source_url: im.url || 'https://exemplo.com',
        evaluation_score: score,
        priority
      }
    });
  }
}
return results;
